cd /workspace && cat > /tmp/mainpage_graph.mjs <<'EOF'
const BASE='http://localhost:5173';
let seen=new Set(), failed=[], ok=0;
async function walk(url, parent){
  if(seen.has(url))return; seen.add(url);
  let text,status; try{ const r=await fetch(BASE+url,{signal:AbortSignal.timeout(20000)}); status=r.status; text=await r.text(); }catch(e){ failed.push(`${url} -> fetch ERR`); return; }
  if(status!==200){ failed.push(`${url} -> HTTP ${status} (imported by ${parent})`); return; }
  const m=text.match(/"message":"([^"]+)"/);
  if(m && /Failed to resolve|no such file/i.test(m[1])){ failed.push(`${url} -> ${m[1]} (imported by ${parent})`); return; }
  ok++;
  const specs=new Set();
  for(const mm of text.matchAll(/import\s*\(\s*["']([^"']+)["']\s*\)/g)) specs.add(mm[1]);
  for(const mm of text.matchAll(/from\s+["']([^"']+)["']/g)) specs.add(mm[1]);
  // only count static imports that look like real specifiers; skip JSDoc comments by checking the char before
  for(const mm of text.matchAll(/import\s+["']([^"']+)["']/g)) specs.add(mm[1]);
  const segs=url.split('/').filter(Boolean); const dir=segs.slice(0,-1);
  for(let s of specs){
    // skip if preceded by comment marker (JSDoc type)
    let t=null;
    if(s.startsWith('./')||s.startsWith('../')){ const parts=dir.concat(s.split('/')); const out=[]; for(const p of parts){ if(p==='.')continue; if(p==='..')out.pop(); else out.push(p);} t='/'+out.join('/'); }
    else if(s.startsWith('@/')) t='/resources/js/'+s.slice(2);
    else if(s.startsWith('/')) t=s; else continue;
    await walk(t, url);
  }
}
// Walk ONLY the main page (the garden map at /) — not the whole glob
await walk('/resources/js/pages/MainPage.vue', '(root: MainPage)');
console.log('MainPage.vue reachable modules resolved OK:', ok);
console.log('FAILED:', failed.length);
for(const f of [...new Set(failed)]) console.log('  ', f);
EOF
